INSERT INTO categorias (id, nombre, descripcion) VALUES
    ('frescas', 'Frutas Frescas', 'Nuestra selección de frutas frescas ofrece una experiencia directa del campo a tu hogar. Estas frutas se cultivan y cosechan en el punto óptimo de madurez para asegurar su sabor y frescura. Disfruta de una variedad de frutas de temporada que aportan vitaminas y nutrientes esenciales a tu dieta diaria. Perfectas para consumir solas, en ensaladas o como ingrediente principal en postres y smoothies.'),
    ('organicas', 'Verduras Orgánicas', 'Descubre nuestra gama de verduras orgánicas, cultivadas sin el uso de pesticidas ni químicos, garantizando un sabor auténtico y natural. Cada verdura es seleccionada por su calidad y valor nutricional, ofreciendo una excelente fuente de vitaminas, minerales y fibra. Ideales para ensaladas, guisos y platos saludables, nuestras verduras orgánicas promueven una alimentación consciente y sostenible.'),
    ('organicos', 'Productos Orgánicos', 'Nuestros productos orgánicos están elaborados con ingredientes naturales y procesados de manera responsable para mantener sus beneficios saludables. Desde aceites y miel hasta granos y semillas, ofrecemos una selección que apoya un estilo de vida saludable y respetuoso con el medio ambiente. Estos productos son perfectos para quienes buscan opciones alimenticias que aporten bienestar sin comprometer el sabor ni la calidad.'),
    ('lacteos', 'Productos Lácteos', 'Los productos lácteos de HuertoHogar provienen de granjas locales que se dedican a la producción responsable y de calidad. Ofrecemos una gama de leches, yogures y otros derivados que conservan su frescura y sabor auténtico. Ricos en calcio y nutrientes esenciales, nuestros lácteos son perfectos para complementar una dieta equilibrada, proporcionando el mejor sabor y nutrición para toda la familia.');
INSERT INTO productos (id, categoria_id, nombre, descripcion, precio, precio_oferta, stock, unidad, origen, imagen) VALUES
    ('FR001', 'frescas', 'Manzanas Fuji', 'Manzanas Fuji crujientes y dulces, cultivadas en el Valle del Maule. Perfectas para meriendas saludables o como ingrediente en postres. Estas manzanas son conocidas por su textura firme y su sabor equilibrado entre dulce y ácido.', 1200, 990, 150, 'kilo', 'Valle del Maule', '/images/manzanas.jpeg'),
    ('FR002', 'frescas', 'Naranjas Valencia', 'Jugosas y ricas en vitamina C, estas naranjas Valencia son ideales para zumos frescos y refrescantes. Cultivadas en condiciones climáticas óptimas que aseguran su dulzura y jugosidad.', 1000, NULL, 200, 'kilo', 'Región de Coquimbo', '/images/naranjas.jpeg'),
    ('FR003', 'frescas', 'Plátanos Cavendish', 'Plátanos maduros y dulces, perfectos para el desayuno o como snack energético. Estos plátanos son ricos en potasio y vitaminas, ideales para mantener una dieta equilibrada.', 800, NULL, 250, 'kilo', 'Región de Arica y Parinacota', '/images/platanos.jpg'),
    ('VR001', 'organicas', 'Zanahorias Orgánicas', 'Zanahorias crujientes cultivadas sin pesticidas en la Región de O''Higgins. Excelente fuente de vitamina A y fibra, ideales para ensaladas, jugos o como snack saludable.', 900, 790, 100, 'kilo', 'Región de O''Higgins', '/images/zanahorias.jpeg'),
    ('VR002', 'organicas', 'Espinacas Frescas', 'Espinacas frescas y nutritivas, perfectas para ensaladas y batidos verdes. Estas espinacas son cultivadas bajo prácticas orgánicas que garantizan su calidad y valor nutricional.', 700, NULL, 80, 'bolsa de 500g', 'Región Metropolitana', '/images/espinacas.jpg'),
    ('VR003', 'organicas', 'Pimientos Tricolores', 'Pimientos rojos, amarillos y verdes, ideales para salteados y platos coloridos. Ricos en antioxidantes y vitaminas, estos pimientos añaden un toque vibrante y saludable a cualquier receta.', 1500, 1290, 120, 'kilo', 'Región del Maule', '/images/pimientos.jpg'),
    ('PO001', 'organicos', 'Miel Orgánica', 'Miel pura y orgánica producida por apicultores locales. Rica en antioxidantes y con un sabor inigualable, perfecta para endulzar de manera natural tus comidas y bebidas.', 5000, NULL, 50, 'frasco de 500g', 'Región de La Araucanía', '/images/miel.jpg');
